From 14560497eaa3f54e43bd9fdb0c9089aaed7d98ef Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 18:52:07 +0100
Subject: [PATCH] applets/notifications: register apps that only show job
 notifications

Apps were only added to the per-app notification settings after sending
a normal notification, so apps like Dolphin that only report file jobs
could not be configured. Register them when their job popup is shown too.

BUG: 524585
---
 applets/notifications/global/Globals.qml | 14 +++++++-------
 1 file changed, 7 insertions(+), 7 deletions(-)

diff --git a/applets/notifications/global/Globals.qml b/applets/notifications/global/Globals.qml
index 8e8e56f88d..7acd2465a4 100644
--- a/applets/notifications/global/Globals.qml
+++ b/applets/notifications/global/Globals.qml
@@ -685,14 +685,14 @@ QtObject {
                     model.wasAddedDuringInhibition = false; // Don't count already shown notifications
                 }

-                if (type === NotificationManager.Notifications.NotificationType && desktopEntry) {
-                    // Register apps that were seen spawning a popup so they can be configured later
-                    // Apps with notifyrc can already be configured anyway
-                    if (!notifyRcName) {
-                        globals.notificationSettings.registerKnownApplication(desktopEntry);
-                        globals.notificationSettings.save();
-                    }
+                // Register apps that were seen spawning a popup so they can be configured later
+                // Apps with notifyrc can already be configured anyway
+                if (desktopEntry && !notifyRcName) {
+                    globals.notificationSettings.registerKnownApplication(desktopEntry);
+                    globals.notificationSettings.save();
+                }

+                if (type === NotificationManager.Notifications.NotificationType && desktopEntry) {
                     // If there is no default action, check if there is a window we could activate instead
                     if (!popup.hasDefaultAction) {
                         for (let i = 0; i < globals.tasksModel.rowCount(); ++i) {
